parameters.jsCode:
const leadData = $('Lead Intake Endpoint').first().json;
const aiResponse = $('🧠 AI Qualification Engine').first().json;

// Parse AI response if it's a string
let qualification;
try {
  qualification = typeof aiResponse.choices[0].message.content === 'string' 
    ? JSON.parse(aiResponse.choices[0].message.content)
    : aiResponse.choices[0].message.content;
} catch (e) {
  qualification = {
    score: 50,
    tier: 'LUKEWARM',
    reasoning: 'Error parsing AI response',
    red_flags: ['AI parsing failed'],
    recommended_action: 'Manual review required',
    urgency_level: 'medium',
    estimated_close_probability: '30%',
    recommended_agent_profile: 'mid-level'
  };
}

// Calculate follow-up timing
const followUpTiming = {
  'HOT': { hours: 0.5, priority: 1 },
  'WARM': { hours: 4, priority: 2 },
  'LUKEWARM': { hours: 24, priority: 3 },
  'COLD': { hours: 72, priority: 4 }
};

const timing = followUpTiming[qualification.tier] || followUpTiming.LUKEWARM;
const followUpTime = new Date();
followUpTime.setHours(followUpTime.getHours() + timing.hours);

// Determine routing
const shouldAutoReject = qualification.score < 20 || 
  (qualification.red_flags && qualification.red_flags.length > 3);

const assignToSeniorAgent = qualification.score >= 80 || 
  qualification.recommended_agent_profile === 'senior';

return {
  json: {
    lead_id: leadData.id || null,
    email: leadData.email,
    phone: leadData.phone,
    first_name: leadData.first_name,
    last_name: leadData.last_name,
    qualification_score: qualification.score,
    qualification_tier: qualification.tier,
    reasoning: qualification.reasoning,
    red_flags: qualification.red_flags || [],
    recommended_action: qualification.recommended_action,
    urgency_level: qualification.urgency_level,
    close_probability: qualification.estimated_close_probability,
    agent_profile: qualification.recommended_agent_profile,
    priority: timing.priority,
    follow_up_at: followUpTime.toISOString(),
    should_auto_reject: shouldAutoReject,
    assign_to_senior: assignToSeniorAgent,
    qualified_at: new Date().toISOString(),
    raw_lead_data: leadData,
    ai_full_response: qualification
  }
};

